class Sidebar{collapseExpandSidebar(){$("#sidebarCollapse").on("click",function(){$("#sidebar").toggleClass("active")})}activeLink(){var n=location.pathname;$(".vertical-nav-menu li a").each(function(){var t=$(this);t.attr("href")===n&&t.addClass("active")})}}let sideBar=new Sidebar;sideBar.collapseExpandSidebar();sideBar.activeLink();